--- Button component.
---
--- Returns a normalized button spec with auto-generated id.
--- Ids are stable when provided, allowing dynamic widget usage.

local color = require("hollow.color")

local M = {}

local counter = 0

-- Theme keys per kind. Default emphasis has no bg key: it brightens `selected_bg`.
local KINDS = {
  default = { fg = "fg", emphasized_fg = "selected_fg" },
  primary = { fg = "primary_bg", emphasized_fg = "primary_fg", emphasized_bg = "primary_bg" },
  destructive = {
    fg = "destructive_bg",
    emphasized_fg = "destructive_fg",
    emphasized_bg = "destructive_bg",
  },
}

--- Reset the auto-id counter. Called once per render pass so autogenerated
--- ids stay stable across frames (hover state set on frame N must match the
--- id regenerated on frame N+1).
function M.reset()
  counter = 0
end

---@param opts { id?: string, text: string, kind?: "default"|"primary"|"destructive", on_click?: fun(e: { id: string }) }
---@return HollowUiDialogButton
function M.button(opts)
  opts = opts or {}
  if type(opts.text) ~= "string" or opts.text == "" then
    error("dialog buttons require a 'text' string")
  end

  counter = counter + 1
  local id = opts.id or ("dialog:button:" .. counter)

  return {
    _button = true,
    id = id,
    text = opts.text,
    kind = opts.kind or "default",
    on_click = opts.on_click,
  }
end

---@param theme table
---@param btn HollowUiDialogButton
---@param selected boolean
---@param hovered boolean
---@return { fg: string, bg?: string, bold?: boolean, radius: integer }
function M.button_style(theme, btn, selected, hovered)
  local kind = KINDS[btn.kind] or KINDS.default
  local radius = theme.radius or 4
  if not (selected or hovered) then
    return { fg = theme[kind.fg], radius = radius }
  end
  local bg
  if kind.emphasized_bg then
    bg = theme[kind.emphasized_bg]
  else
    bg = color.brighten_hex_color(theme.selected_bg, 0.25, theme.panel_bg)
  end
  return { fg = theme[kind.emphasized_fg], bg = bg, bold = true, radius = radius }
end

return M
